	public static void CreateAlpha1Party(global::Pml.PokeParty party) {
        if (party == null || party.GetMemberCount() != 0)
            return;

        Dpr.EncountTools.CreateSimpleParty(MonsNo.HIKOZARU, 20, MonsNo.SUBOMII, 10, party);

        // byte index (`and w20, w8, #0xff` @02cf1dfc); playerStatus ref getter inlined (flag 0x4edbeb5)
        for (byte i = 0; i < party.GetMemberCount(); i++)
            poketool.poke_memo.poketool_poke_memo.SetFromCapture(party.GetMemberPointer(i), playerStatus, ZoneID.UNKNOWN);

        ItemWork.AddItem((int)ItemNo.MONSUTAABOORU, 30);
        ItemWork.AddItem((int)ItemNo.KIZUGUSURI, 30);

        for (uint i = 0; i < party.GetMemberCount(); i++)
            ZukanWork.SetPoke(party.GetMemberPointer(i), GET_STATUS.GET);
    }
