	public static int GetTrainerRank() {
        int rank = 0;

        if (FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_GAME_CLEAR))
            rank++;

        if (ZukanWork.CheckZenkokuZukanCompGet())
            rank++;

        if (RecordWork.Get(RECORD_ID.RECID_RENSHOU_SINGLE) >= 100 ||
            RecordWork.Get(RECORD_ID.RECID_RENSHOU_DOUBLE) >= 100 ||
            RecordWork.Get(RECORD_ID.RECID_RENSHOU_MASTER_SINGLE) >= 100 ||
            RecordWork.Get(RECORD_ID.RECID_RENSHOU_MASTER_DOUBLE) >= 100)
            rank++;

        if (FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_CON_STYLE_MASTER) ||
            FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_CON_BEAUTIFUL_MASTER) ||
            FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_CON_CUTE_MASTER) ||
            FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_CON_CLEVER_MASTER) ||
            FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_CON_STRONG_MASTER))
            rank++;

        if (UgItemWork.GetHaveStatueKindNum() >= 100)
            rank++;

        return rank < MYSTATUS.TRAINER_RANK_MAX ? rank : MYSTATUS.TRAINER_RANK_MAX;
    }
