	public static bool VerifySaveData(byte[] byteArray) {
        int version = byteArray[0] | (byteArray[1] << 8) | (byteArray[2] << 16) | (byteArray[3] << 24);
        if (version < SaveData.LAUNCH_VERSION)
            return true;

        int count = SaveData.BINARY_SIZE[version - SaveData.LAUNCH_VERSION];
        byte[] hash = new byte[SaveData.SAVEDATA_HASH_SIZE];
        bool result;

        // using → try / finally with an IDisposable interface Dispose (@02cebdb8); leave targets 0xa0 / 0xb1
        using (var crypto = new MD5CryptoServiceProvider())
        {
            if (byteArray.Length < SaveData.SAVEDATA_HASH_ADDR + SaveData.SAVEDATA_HASH_SIZE)
                return false;

            Array.Copy(byteArray, SaveData.SAVEDATA_HASH_ADDR, hash, 0, SaveData.SAVEDATA_HASH_SIZE);
            Array.Clear(byteArray, SaveData.SAVEDATA_HASH_ADDR, SaveData.SAVEDATA_HASH_SIZE);
            byte[] computed = crypto.ComputeHash(byteArray, 0, count);

            result = true;
            for (int i = 0; i < SaveData.SAVEDATA_HASH_SIZE; i++)
            {
                if (hash[i] != computed[i])
                {
                    result = false;
                    break;
                }
            }
        }

        Array.Copy(hash, 0, byteArray, SaveData.SAVEDATA_HASH_ADDR, SaveData.SAVEDATA_HASH_SIZE);
        return result;
    }
